def can_partition_k_subsets(nums: list[int], k: int) -> bool:
    total = sum(nums)
    if total % k:
        return False
    target = total // k
    nums = sorted(nums, reverse=True)  # big items first fail fast
    if nums[0] > target:
        return False
    n = len(nums)
    full = (1 << n) - 1
    failed = set()  # masks from which the remaining groups cannot be completed

    def dfs(mask, filled):
        # filled = how much of the current group is already used (sum of mask mod target)
        if mask == full:
            return True
        if mask in failed:
            return False
        prev = None
        for i in range(n):
            if mask >> i & 1 or nums[i] == prev or filled + nums[i] > target:
                continue
            if dfs(mask | (1 << i), (filled + nums[i]) % target):
                return True
            prev = nums[i]       # an equal value would fail the same way
            if filled == 0:
                break            # a new group must contain the largest unused item anyway
        failed.add(mask)
        return False

    return dfs(0, 0)

def array_rank_transform(arr: list[int]) -> list[int]:
    # Rank of each distinct value = its position in sorted order, plus one.
    rank = {value: i + 1 for i, value in enumerate(sorted(set(arr)))}
    return [rank[value] for value in arr]

