def knight_probability(n: int, k: int, row: int, column: int) -> float:
    moves = [(1, 2), (2, 1), (2, -1), (1, -2),
             (-1, -2), (-2, -1), (-2, 1), (-1, 2)]
    # Precompute, for every cell, the list of on board targets.
    targets = [[[(r + dr, c + dc) for dr, dc in moves
                 if 0 <= r + dr < n and 0 <= c + dc < n]
                for c in range(n)] for r in range(n)]
    prob = [[0.0] * n for _ in range(n)]
    prob[row][column] = 1.0
    for _ in range(k):
        nxt = [[0.0] * n for _ in range(n)]
        for r in range(n):
            for c in range(n):
                share = prob[r][c]
                if share:
                    share /= 8.0
                    for tr, tc in targets[r][c]:
                        nxt[tr][tc] += share
        prob = nxt
    return sum(map(sum, prob))

