def ip_to_cidr(ip: str, n: int) -> list[str]:
    x = 0
    for part in ip.split("."):
        x = x * 256 + int(part)

    def to_ip(v: int) -> str:
        return ".".join(str((v >> shift) & 255) for shift in (24, 16, 8, 0))

    blocks = []
    while n > 0:
        size = x & -x if x else 1 << 32    # largest block aligned at x
        while size > n:                    # but no bigger than what is left
            size >>= 1
        prefix = 32 - (size.bit_length() - 1)
        blocks.append(f"{to_ip(x)}/{prefix}")
        x += size
        n -= size
    return blocks

