def maximum_xor_product(a: int, b: int, n: int) -> int:
    MOD = 10 ** 9 + 7
    for i in range(n - 1, -1, -1):
        bit = 1 << i
        if (a & bit) == (b & bit):
            # Same bit: x can make both of them 1 here.
            a |= bit
            b |= bit
        elif a < b:
            # Different bits: give the 1 to the smaller factor.
            a |= bit
            b &= ~bit
        else:
            b |= bit
            a &= ~bit
    return (a % MOD) * (b % MOD) % MOD

