def number_of_sets(n: int, maxDistance: int, roads: list[list[int]]) -> int:
    INF = float("inf")
    # Shortest direct road between every pair of branches.
    direct = [[INF] * n for _ in range(n)]
    for i in range(n):
        direct[i][i] = 0
    for u, v, w in roads:
        if w < direct[u][v]:
            direct[u][v] = direct[v][u] = w

    valid = 0
    for mask in range(1 << n):
        kept = [i for i in range(n) if mask >> i & 1]
        dist = [[direct[i][j] for j in kept] for i in kept]
        size = len(kept)
        # Floyd Warshall restricted to the kept branches.
        for mid in range(size):
            via = dist[mid]
            for i in range(size):
                row = dist[i]
                to_mid = row[mid]
                if to_mid == INF:
                    continue
                for j in range(size):
                    cand = to_mid + via[j]
                    if cand < row[j]:
                        row[j] = cand
        if all(d <= maxDistance for row in dist for d in row):
            valid += 1
    return valid

def get_number_of_backlog_orders(orders: list[list[int]]) -> int:
    MOD = 10 ** 9 + 7
    buys = []    # max heap via negated price: [-price, amount]
    sells = []   # min heap: [price, amount]
    for price, amount, kind in orders:
        if kind == 0:
            # Buy: match against the cheapest sells priced <= price.
            while amount and sells and sells[0][0] <= price:
                take = min(amount, sells[0][1])
                amount -= take
                sells[0][1] -= take
                if sells[0][1] == 0:
                    heapq.heappop(sells)
            if amount:
                heapq.heappush(buys, [-price, amount])
        else:
            # Sell: match against the highest buys priced >= price.
            while amount and buys and -buys[0][0] >= price:
                take = min(amount, buys[0][1])
                amount -= take
                buys[0][1] -= take
                if buys[0][1] == 0:
                    heapq.heappop(buys)
            if amount:
                heapq.heappush(sells, [price, amount])
    return (sum(a for _, a in buys) + sum(a for _, a in sells)) % MOD

