def get_directions(root: Optional[TreeNode], startValue: int, destValue: int) -> str:
    # Map each value to (parent node, move from parent) while traversing.
    link = {root.val: (None, "")}
    node_of = {root.val: root}
    stack = [root]
    while stack:
        node = stack.pop()
        for child, move in ((node.left, "L"), (node.right, "R")):
            if child:
                link[child.val] = (node, move)
                node_of[child.val] = child
                stack.append(child)

    def path_from_root(value):
        moves = []
        node = node_of[value]
        while link[node.val][0] is not None:
            parent, move = link[node.val]
            moves.append(move)
            node = parent
        return moves[::-1]

    to_start, to_dest = path_from_root(startValue), path_from_root(destValue)
    # Skip the shared prefix: it leads down to the lowest common ancestor.
    i = 0
    while i < len(to_start) and i < len(to_dest) and to_start[i] == to_dest[i]:
        i += 1
    return "U" * (len(to_start) - i) + "".join(to_dest[i:])

