def count_unguarded(m: int, n: int, guards: list[list[int]], walls: list[list[int]]) -> int:
    FREE, GUARD, WALL, SEEN = 0, 1, 2, 3
    grid = [FREE] * (m * n)          # flattened: cell (r, c) -> r * n + c
    for r, c in guards:
        grid[r * n + c] = GUARD
    for r, c in walls:
        grid[r * n + c] = WALL

    def sweep(indices):
        watching = False
        for idx in indices:
            cell = grid[idx]
            if cell == GUARD:
                watching = True
            elif cell == WALL:
                watching = False
            elif watching:
                grid[idx] = SEEN

    for r in range(m):
        row = range(r * n, r * n + n)
        sweep(row)
        sweep(reversed(row))
    for c in range(n):
        col = range(c, m * n, n)
        sweep(col)
        sweep(reversed(col))
    return grid.count(FREE)

def words_abbreviation(words: list[str]) -> list[str]:
    def lcp(a: str, b: str) -> int:
        k = 0
        while k < len(a) and a[k] == b[k]:
            k += 1
        return k

    def build(word: str, prefix: int) -> str:
        abbr = word[:prefix] + str(len(word) - prefix - 1) + word[-1]
        return abbr if len(abbr) < len(word) else word

    # Only words with the same length, first and last letter can clash.
    groups = defaultdict(list)
    for i, w in enumerate(words):
        groups[(len(w), w[0], w[-1])].append(i)

    result = [""] * len(words)
    for members in groups.values():
        members.sort(key=lambda i: words[i])
        need = [1] * len(members)          # prefix length each word needs
        for a in range(len(members) - 1):
            common = lcp(words[members[a]], words[members[a + 1]])
            need[a] = max(need[a], common + 1)
            need[a + 1] = max(need[a + 1], common + 1)
        for idx, prefix in zip(members, need):
            result[idx] = build(words[idx], prefix)
    return result

