class ZigzagIterator:
    def __init__(self, v1: list[int], v2: list[int]):
        # One [list, next index] entry per list that still has elements.
        self.queue = deque([v, 0] for v in (v1, v2) if v)

    def next(self) -> int:
        entry = self.queue.popleft()
        values, idx = entry
        entry[1] = idx + 1
        if idx + 1 < len(values):
            self.queue.append(entry)     # still has elements; back of the line
        return values[idx]

    def hasNext(self) -> bool:
        return bool(self.queue)

