def shortest_substrings(arr: list[str]) -> list[str]:
    # All distinct substrings of each string.
    subs = []
    for s in arr:
        subs.append({s[i:j] for i in range(len(s)) for j in range(i + 1, len(s) + 1)})
    # How many strings contain each substring.
    owners = Counter()
    for group in subs:
        owners.update(group)

    answer = []
    for s, group in zip(arr, subs):
        best = ""
        for length in range(1, len(s) + 1):
            unique = [t for t in group if len(t) == length and owners[t] == 1]
            if unique:
                best = min(unique)
                break
        answer.append(best)
    return answer

