def count_good_strings(low: int, high: int, zero: int, one: int) -> int:
    MOD = 10 ** 9 + 7
    ways = [0] * (high + 1)
    ways[0] = 1                      # the empty string
    total = 0
    for length in range(1, high + 1):
        count = 0
        if length >= zero:
            count += ways[length - zero]
        if length >= one:
            count += ways[length - one]
        ways[length] = count % MOD
        if length >= low:
            total = (total + ways[length]) % MOD
    return total

def process_queries(c: int, connections: List[List[int]], queries: List[List[int]]) -> List[int]:
    parent = list(range(c + 1))

    def find(x: int) -> int:
        while parent[x] != x:
            parent[x] = parent[parent[x]]   # path halving
            x = parent[x]
        return x

    for u, v in connections:
        ru, rv = find(u), find(v)
        if ru != rv:
            parent[ru] = rv

    grid_of = [find(s) for s in range(c + 1)]
    heaps = defaultdict(list)
    for station in range(1, c + 1):          # increasing order keeps each list a valid heap
        heaps[grid_of[station]].append(station)

    online = [True] * (c + 1)
    answers = []
    for kind, x in queries:
        if kind == 2:
            online[x] = False
            continue
        if online[x]:
            answers.append(x)
            continue
        heap = heaps[grid_of[x]]
        while heap and not online[heap[0]]:
            heapq.heappop(heap)              # lazy deletion of offline stations
        answers.append(heap[0] if heap else -1)
    return answers

