def inorder_successor(root: Optional[TreeNode], p: TreeNode) -> Optional[TreeNode]:
    successor = None
    node = root
    while node:
        if node.val > p.val:
            # A candidate; a closer one can only be on the left.
            successor = node
            node = node.left
        else:
            # Too small: larger values live on the right.
            node = node.right
    return successor

def count_arrangement(n: int) -> int:
    # compatible[i] = bitmask of numbers allowed at 1 based position i
    compatible = [0] * (n + 1)
    for i in range(1, n + 1):
        for v in range(1, n + 1):
            if v % i == 0 or i % v == 0:
                compatible[i] |= 1 << (v - 1)

    full = (1 << n) - 1
    dp = [0] * (1 << n)
    dp[0] = 1
    for mask in range(1 << n):
        ways = dp[mask]
        if not ways or mask == full:
            continue
        pos = bin(mask).count("1") + 1          # next position to fill
        options = compatible[pos] & ~mask
        while options:
            bit = options & -options
            dp[mask | bit] += ways
            options ^= bit
    return dp[full]

def close_strings(word1: str, word2: str) -> bool:
    if len(word1) != len(word2):
        return False
    c1, c2 = Counter(word1), Counter(word2)
    # Same letters present, and the same multiset of frequencies.
    return set(c1) == set(c2) and sorted(c1.values()) == sorted(c2.values())

def max_diff(num: int) -> int:
    s = str(num)

    # Largest: raise the first digit that is not already 9.
    high = s
    for ch in s:
        if ch != "9":
            high = s.replace(ch, "9")
            break

    # Smallest: lower the leading digit to 1, or else a later digit to 0.
    low = s
    if s[0] != "1":
        low = s.replace(s[0], "1")
    else:
        for ch in s[1:]:
            if ch not in "01":
                low = s.replace(ch, "0")
                break

    return int(high) - int(low)

def hit_bricks(grid: List[List[int]], hits: List[List[int]]) -> List[int]:
    m, n = len(grid), len(grid[0])
    g = [row[:] for row in grid]
    for r, c in hits:
        g[r][c] -= 1            # 0 means removed brick, -1 means hit on empty cell

    roof = m * n
    parent = list(range(m * n + 1))
    size = [1] * (m * n + 1)

    def find(x: int) -> int:
        while parent[x] != x:
            parent[x] = parent[parent[x]]
            x = parent[x]
        return x

    def union(a: int, b: int) -> None:
        ra, rb = find(a), find(b)
        if ra == rb:
            return
        if size[ra] < size[rb]:
            ra, rb = rb, ra
        parent[rb] = ra
        size[ra] += size[rb]

    # Union find over the grid left after every hit.
    for r in range(m):
        for c in range(n):
            if g[r][c] == 1:
                idx = r * n + c
                if r == 0:
                    union(idx, roof)
                if r > 0 and g[r - 1][c] == 1:
                    union(idx, idx - n)
                if c > 0 and g[r][c - 1] == 1:
                    union(idx, idx - 1)

    result = [0] * len(hits)
    for k in range(len(hits) - 1, -1, -1):
        r, c = hits[k]
        g[r][c] += 1
        if g[r][c] != 1:
            continue            # there was no brick here originally
        before = size[find(roof)]
        idx = r * n + c
        if r == 0:
            union(idx, roof)
        for dr, dc in ((1, 0), (-1, 0), (0, 1), (0, -1)):
            rr, cc = r + dr, c + dc
            if 0 <= rr < m and 0 <= cc < n and g[rr][cc] == 1:
                union(idx, rr * n + cc)
        after = size[find(roof)]
        # Newly attached bricks, minus the restored brick itself.
        result[k] = max(0, after - before - 1)
    return result

